CREATE TABLE IF NOT EXISTS prontuario (id BIGSERIAL PRIMARY KEY, tenant_id UUID NOT NULL, beneficiario_id BIGINT NOT NULL, numero_prontuario VARCHAR(40) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'ATIVO', criado_em TIMESTAMP NOT NULL DEFAULT NOW(), atualizado_em TIMESTAMP NOT NULL DEFAULT NOW(), CONSTRAINT prontuario_tenant_beneficiario_unq UNIQUE (tenant_id, beneficiario_id), CONSTRAINT prontuario_tenant_numero_unq UNIQUE (tenant_id, numero_prontuario));
CREATE TABLE IF NOT EXISTS prontuario_atendimento (id BIGSERIAL PRIMARY KEY, tenant_id UUID NOT NULL, prontuario_id BIGINT NOT NULL REFERENCES prontuario(id) ON DELETE CASCADE, beneficiario_id BIGINT NOT NULL, profissional_id BIGINT, usuario_id BIGINT, unidade_id BIGINT, profissional_nome VARCHAR(200) NOT NULL, profissional_categoria VARCHAR(160), unidade_nome VARCHAR(200), especialidade VARCHAR(160) NOT NULL, tipo_atendimento VARCHAR(160) NOT NULL, data_atendimento DATE NOT NULL DEFAULT CURRENT_DATE, hora_inicio TIMESTAMP, hora_fim TIMESTAMP, duracao_minutos INTEGER, status VARCHAR(30) NOT NULL DEFAULT 'RASCUNHO', motivo TEXT, demanda_principal TEXT, avaliacao TEXT, evolucao TEXT, intervencoes JSONB NOT NULL DEFAULT '[]'::jsonb, conduta TEXT, retorno_data DATE, observacoes TEXT, campos_especificos JSONB NOT NULL DEFAULT '{}'::jsonb, restrito BOOLEAN NOT NULL DEFAULT FALSE, finalizado_em TIMESTAMP, criado_em TIMESTAMP NOT NULL DEFAULT NOW(), atualizado_em TIMESTAMP NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS prontuario_atendimento_tenant_beneficiario_idx ON prontuario_atendimento(tenant_id, beneficiario_id, data_atendimento DESC);
CREATE INDEX IF NOT EXISTS prontuario_atendimento_status_idx ON prontuario_atendimento(tenant_id, status);
CREATE TABLE IF NOT EXISTS prontuario_adendo (id BIGSERIAL PRIMARY KEY, tenant_id UUID NOT NULL, atendimento_id BIGINT NOT NULL REFERENCES prontuario_atendimento(id) ON DELETE CASCADE, conteudo TEXT NOT NULL, motivo TEXT, usuario_id BIGINT, usuario_nome VARCHAR(200) NOT NULL, criado_em TIMESTAMP NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS prontuario_adendo_atendimento_idx ON prontuario_adendo(tenant_id, atendimento_id, criado_em DESC);
CREATE TABLE IF NOT EXISTS prontuario_auditoria (id BIGSERIAL PRIMARY KEY, tenant_id UUID NOT NULL, prontuario_id BIGINT, atendimento_id BIGINT, acao VARCHAR(60) NOT NULL, descricao TEXT NOT NULL, usuario_id BIGINT, usuario_nome VARCHAR(200), criado_em TIMESTAMP NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS prontuario_auditoria_atendimento_idx ON prontuario_auditoria(tenant_id, atendimento_id, criado_em DESC);
